import('./Space_Invaders/simulation.js').then(async (sim) => {
  const { createSim, updateSim, EV } = sim;
  const s = createSim(42);
  let kills = 0, ufoKills = 0, playerHits = 0, waveClears = 0, shieldChips = 0;
  const dt = 1/60;
  let t = 0;
  // Simple AI: track the lowest invader's x, fire always.
  while (s.state !== 'gameover' && t < 120) {
    // aim at the lowest alive invader
    let targetX = 0;
    const f = s.formation;
    for (let r = 4; r >= 0 && targetX === 0; r--) {
      for (let c = 0; c < 11; c++) {
        if (f.alive[r*11+c]) { targetX = f.baseX + (c-5)*1.3; break; }
      }
    }
    const dir = Math.max(-1, Math.min(1, (targetX - s.player.x) * 0.5));
    updateSim(s, dt, { x: dir, fire: true });
    for (const e of s.events) {
      if (e.type === EV.ENEMY_DEATH) kills++;
      if (e.type === EV.UFO_KILL) ufoKills++;
      if (e.type === EV.PLAYER_HIT) playerHits++;
      if (e.type === EV.WAVE_CLEAR) waveClears++;
      if (e.type === EV.SHIELD_CHIP) shieldChips++;
    }
    s.events.length = 0;
    t += dt;
  }
  console.log('t=', t.toFixed(1)+'s', 'state=', s.state);
  console.log('kills=', kills, 'ufoKills=', ufoKills, 'playerHits=', playerHits, 'waveClears=', waveClears, 'shieldChips=', shieldChips);
  console.log('score=', s.score, 'wave=', s.wave, 'lives=', s.lives, 'highScore=', s.highScore);
