import('./Space_Invaders/simulation.js').then(async (sim) => {
  const { createSim, updateSim, EV, invaderWorldPos } = sim;
  const s = createSim(42);
  // Disable enemy fire so only the player bullet matters.
  // We can't easily disable it, so instead: put player at x=0, fire once,
  // and trace ONLY the player bullet's path and collisions.
  s.player.x = 0; s.player.vx = 0;
  const dt = 1/60;
  // Manually step the player bullet through the world and check invader AABBs.
  // Simulate: bullet starts at y=2.4, vy=60.
  let by = 2.4, bpx = 0, bpy = 2.4;
  const invW = 1.0, invH = 0.9;
  let hitRow = -1, hitCol = -1;
  for (let step = 0; step < 200; step++) {
    by += 60 * dt;
    // check all invaders
    for (let r = 0; r < 5 && hitRow < 0; r++) {
      for (let c = 0; c < 11 && hitRow < 0; c++) {
        if (!s.formation.alive[r*11+c]) continue;
        const p = {x:0,y:0,z:0};
        invaderWorldPos(s, r, c, p);
        // swept AABB
        const minx = p.x - invW/2, maxx = p.x + invW/2;
        const miny = p.y - invH/2, maxy = p.y + invH/2;
        const p0y = bpy, p1y = by;
        // x is constant 0
        if (0 >= minx && 0 <= maxx) {
          if (p0y <= maxy && p1y >= miny) {
            hitRow = r; hitCol = c;
            console.log('HIT invader row', r, 'col', c, 'at bullet y', by.toFixed(2), 'invader y', p.y.toFixed(2));
          }
        }
      }
    }
    bpy = by;
    if (hitRow >= 0) break;
  }
  console.log('manual trace: hitRow=', hitRow, 'hitCol=', hitCol);
  // Also: is the center invader (row 4, col 5) alive?
  console.log('center invader alive?', s.formation.alive[4*11+5]);
  const cp = {x:0,y:0,z:0};
  invaderWorldPos(s, 4, 5, cp);
  console.log('center invader pos:', cp.x.toFixed(2), cp.y.toFixed(2));
}).catch(e => { console.error('FAIL:', e.message); process.exit(1); });
