  await page.goto('http://localhost:5199/Space_Invaders/', { waitUntil: 'load', timeout: 20000 });
  await page.waitForTimeout(1500);

  // Drive the player: hold fire, sweep left/right to hit invaders.
  await page.keyboard.down('Space'); // fire
  for (let sweep = 0; sweep < 6; sweep++) {
    const key = sweep % 2 === 0 ? 'ArrowRight' : 'ArrowLeft';
    await page.keyboard.down(key);
    await page.waitForTimeout(700);
    await page.keyboard.up(key);
    await page.waitForTimeout(150);
  }
  await page.keyboard.up('Space');
  await page.waitForTimeout(500);

  const mid = await page.evaluate(() => {
    const g = window.__spaceInvaders;
    return { score: g.sim.score, alive: g.sim.formation.aliveCount, lives: g.sim.lives, state: g.sim.state, time: g.sim.time.toFixed(1) };
  });
  console.log('AFTER PLAY:', JSON.stringify(mid));

  // Test pause
  await page.keyboard.press('KeyP');
  await page.waitForTimeout(300);
  const paused = await page.evaluate(() => window.__spaceInvaders.paused);
  const t1 = await page.evaluate(() => window.__spaceInvaders.sim.time);
  await page.waitForTimeout(500);
  const t2 = await page.evaluate(() => window.__spaceInvaders.sim.time);
  console.log('PAUSE: paused=', paused, 'timeFrozen=', (t2 - t1).toFixed(3));
  await page.keyboard.press('KeyP'); // unpause

  // Test restart
  await page.keyboard.press('KeyR');
  await page.waitForTimeout(400);
  const afterRestart = await page.evaluate(() => {
    const g = window.__spaceInvaders;
    return { score: g.sim.score, alive: g.sim.formation.aliveCount, state: g.sim.state };
  });
  console.log('AFTER RESTART:', JSON.stringify(afterRestart));

  console.log('ERRORS:', errors.length ? errors.join(' | ') : 'none');
  await browser.close();
})().catch(e => { console.error('FAIL:', e.message); process.exit(1); });
