function visibleY(camPos, target, fovDeg, aspect) {
  const fov = fovDeg * Math.PI/180;
  const tanF = Math.tan(fov/2);
  // view direction
  const dx = target[0]-camPos[0], dy = target[1]-camPos[1], dz = target[2]-camPos[2];
  const len = Math.hypot(dx,dy,dz);
  const d = [dx/len, dy/len, dz/len];
  // distance along view dir to z=0 plane
  const t = (0 - camPos[2]) / d[2];
  // point on z=0 along center ray
  const cy = camPos[1] + d[1]*t;
  // half-height of frustum at that distance
  const halfH = tanF * t;
  // but the frustum is tilted; the vertical extent at z=0 is roughly halfH (approx for small tilt)
  return { centerY: cy, halfH, bottom: cy-halfH, top: cy+halfH };
}
